INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (730, '0b0560ae-87f2-4f7d-bae8-bae46f2ca7cf', 'job.entities.job_trigger.status.me', 'pt-PT', 'Eu', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 1, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (645, '6e91dbb1-77c7-4f7b-a73a-096de4c4bc22', 'job.entities.job_trigger.hints.execution_context', 'en-GB', '`user` runs the action as the triggering user (with their permissions); `me` runs as the trigger''s author — identity resolved fresh at dispatch time; `system` runs with module privileges. Must match the lane in the destination subject.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (646, '87ed4d13-f214-43c6-a615-8980925926fe', 'job.entities.job_trigger.hints.execution_context', 'en-US', '`user` runs the action as the triggering user (with their permissions); `me` runs as the trigger''s author — identity resolved fresh at dispatch time; `system` runs with module privileges. Must match the lane in the destination subject.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (647, 'cc34810a-1d58-4076-9266-424f7514c31c', 'job.entities.job_trigger.hints.execution_context', 'it-IT', '`user` esegue l''azione come l''utente che ha innescato (con i suoi permessi); `me` come l''autore del trigger — identità risolta fresca al momento dell''esecuzione; `system` con i privilegi del modulo. Deve corrispondere alla lane nel soggetto destinazione.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (648, '31b7c3f8-c8f4-4ee7-9f4f-24ae704f3fba', 'job.entities.job_trigger.hints.execution_context', 'de-DE', '`user` führt die Aktion als der auslösende Benutzer aus (mit dessen Berechtigungen); `me` als der Autor des Triggers — Identität wird zum Ausführungszeitpunkt frisch aufgelöst; `system` mit Modulprivilegien. Muss zur Lane im Ziel-Subject passen.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (649, '8e32e8c5-ff38-4b3c-84e1-2ea89fd21963', 'job.entities.job_trigger.hints.execution_context', 'fr-FR', '`user` exécute l''action comme l''utilisateur déclencheur (avec ses permissions) ; `me` comme l''auteur du déclencheur — identité résolue à jour au moment de l''exécution ; `system` avec les privilèges du module. Doit correspondre à la lane du sujet de destination.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (650, '39a0ab2e-2dee-46f8-8b5a-52adcde1b2b7', 'job.entities.job_trigger.hints.execution_context', 'es-ES', '`user` ejecuta la acción como el usuario que disparó (con sus permisos); `me` como el autor del trigger — identidad resuelta al momento de la ejecución; `system` con privilegios del módulo. Debe coincidir con la lane del asunto de destino.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (651, 'fab0b92a-1930-46cd-adb2-7c223c3480b8', 'job.entities.job_trigger.hints.execution_context', 'pt-PT', '`user` executa a ação como o usuário que disparou (com suas permissões); `me` como o autor do trigger — identidade resolvida no momento da execução; `system` com privilégios do módulo. Deve corresponder à lane no assunto de destino.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:32:26.425203+00', 'migration-job-trigger-rename', 2, NULL, NULL);
INSERT INTO job.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (671, 'e2f5bc5c-c6c1-476d-859e-6ffbc0f4e145', 'job.events.triggers_changed.desc', 'es-ES', 'Emitido cuando el conjunto de triggers de job cambia — `jobs` dominio, `ctl` canal de control, `triggers` recurso, `changed` verbo. El motor de triggers rearma las programaciones.', '2026-10-27 17:26:28.604582+00', 'initial-setup', '2026-11-02 20:39:02.207885+00', 'migration-trigger-labels', 3, NULL, NULL);
